{"metadata":{"kernelspec":{"language":"python","display_name":"Python 3","name":"python3"},"language_info":{"name":"python","version":"3.13.15","mimetype":"text/x-python","codemirror_mode":{"name":"ipython","version":3},"pygments_lexer":"ipython3","nbconvert_exporter":"python","file_extension":".py"},"kaggle":{"accelerator":"nvidiaTeslaT4","dataSources":[],"isInternetEnabled":true,"language":"python","sourceType":"notebook","isGpuEnabled":false}},"nbformat_minor":4,"nbformat":4,"cells":[{"cell_type":"code","source":"# This Python 3 environment comes with many helpful analytics libraries installed\n# It is defined by the kaggle/python Docker image: https://github.com/kaggle/docker-python\n# For example, here's several helpful packages to load\n\nimport numpy as np # linear algebra\nimport pandas as pd # data processing, CSV file I/O (e.g. pd.read_csv)\n\n# Input data files are available in the read-only \"../input/\" directory\n# For example, running this (by clicking run or pressing Shift+Enter) will list all files under the input directory\n\nimport os\nfor dirname, _, filenames in os.walk('/kaggle/input'):\n    for filename in filenames:\n        print(os.path.join(dirname, filename))\n\n# You can write up to 20GB to the current directory (/kaggle/working/) that gets preserved as output when you create a version using \"Save & Run All\" \n# You can also write temporary files to /kaggle/temp/, but they won't be saved outside of the current session\n\n# Use the kagglehub client library to attach Kaggle resources like competitions, datasets, and models to your session\n# Learn more about kagglehub: https://github.com/Kaggle/kagglehub/blob/main/README.md\n\nimport kagglehub\n# kagglehub.dataset_download('<owner>/<dataset-slug>')","metadata":{"_uuid":"8f2839f25d086af736a60e9eeb907d3b93b6e0e5","_cell_guid":"b1076dfc-b9ad-4769-8c92-a6c4dae69d19","trusted":true},"outputs":[],"execution_count":null},{"cell_type":"code","source":"","metadata":{"trusted":true},"outputs":[],"execution_count":null},{"cell_type":"code","source":"import cmath\nimport numpy as np\nimport scipy.linalg as LA\n\n\ndef run_fast_lorentzian_audit():\n  print('=== AVVIO AUDIT LORENTZIANO OTTIMIZZATO (KREIN SPACE) ===')\n\n  # 1. Punto stazionario del vuoto certificato\n  psi = 1.465571231876768\n  print(f'Punto stazionario del vuoto: rho_* = psi = {psi}')\n\n  # 2. Matrici fondamentali di Krist-All (3x3)\n  K = np.array([[0, 0, 1], [1, 0, 0], [0, 1, 1]], dtype=float)\n  KT = np.array([[0, 1, 0], [0, 0, 1], [1, 0, 1]], dtype=float)\n  I3 = np.eye(3, dtype=float)\n\n  U_psi = I3 + psi * K + (psi**2) * (K @ K)\n  U_psi_inv = np.linalg.inv(U_psi)\n  U_psi_dag = I3 + psi * KT + (psi**2) * (KT @ KT)\n  det_U = psi**6 - psi**4 - 2 * psi**3 + psi**2 + psi + 1\n  a_p = (-psi**4 - psi**3 + psi**2 + psi + 1) / det_U\n  b_p = (psi * (psi**3 - psi**2 - psi - 1)) / det_U\n  c_p = (psi**3) / det_U\n  U_inv_dag = a_p * I3 + b_p * KT + c_p * (KT @ KT)\n\n  # 3. Griglie angolari dei fattori del grafo C64 x C6^3 x C5\n  angles_64 = [2 * cmath.pi * k / 64 for k in range(64)]\n  angles_6 = [2 * cmath.pi * n / 6 for n in range(6)]\n  angles_5 = [2 * cmath.pi * p / 5 for p in range(5)]\n\n  # Pre-computazione dei generatori di derivata per efficienza estrema\n  # dL/dx_mu = e^{i x_mu} * M1 + e^{-i x_mu} * M2\n  M1 = -0.5j * (U_psi + U_inv_dag)\n  M2 = 0.5j * (U_psi_dag + U_psi_inv)\n\n  print(\n      'Esecuzione dell\\'integrazione d\\'insieme con grading di Krein eta'\n      ' (C64)...'\n  )\n  g_lorentz_5d = np.zeros((5, 5), dtype=float)\n  total_states = 64 * 6 * 6 * 6 * 5  # 69120\n\n  # 4. Ciclo di aggregazione vettorializzato/ottimizzato\n  for k_idx, phi in enumerate(angles_64):\n    eta_temporal_sign = -1.0 if k_idx > 32 else 1.0\n    e_phi = cmath.exp(1j * phi)\n    dL_dphi = e_phi * M1 + cmath.exp(-1j * phi) * M2\n\n    for psi1 in angles_6:\n      e_ps1 = cmath.exp(1j * psi1)\n      dL_dpsi1 = e_ps1 * M1 + cmath.exp(-1j * psi1) * M2\n\n      for psi2 in angles_6:\n        e_ps2 = cmath.exp(1j * psi2)\n        dL_dpsi2 = e_ps2 * M1 + cmath.exp(-1j * psi2) * M2\n\n        for psi3 in angles_6:\n          e_ps3 = cmath.exp(1j * psi3)\n          dL_dpsi3 = e_ps3 * M1 + cmath.exp(-1j * psi3) * M2\n\n          for omega in angles_5:\n            e_om = cmath.exp(1j * omega)\n            dL_domega = e_om * M1 + cmath.exp(-1j * omega) * M2\n\n            dL_dx_list = [dL_dphi, dL_dpsi1, dL_dpsi2, dL_dpsi3, dL_domega]\n\n            # Valore di A per lo stato\n            A_val = e_phi + e_ps1 + e_ps2 + e_ps3 + e_om\n            A_bar = A_val.conjugate()\n\n            L_j = (\n                10 * I3\n                - 0.5 * (A_val * U_psi + A_bar * U_psi_dag)\n                - 0.5 * (A_bar * U_psi_inv + A_val * U_inv_dag)\n            )\n            L_pinv = LA.pinv(L_j)\n\n            # Contributo metrico con Krein grading eta sul canale temporale (indice 0)\n            g_state = np.zeros((5, 5), dtype=float)\n            for A_idx in range(5):\n              for B_idx in range(5):\n                prod = (\n                    L_pinv @ dL_dx_list[A_idx] @ L_pinv @ dL_dx_list[B_idx]\n                )\n                val = np.real(np.trace(prod))\n\n                if A_idx == 0 or B_idx == 0:\n                  val *= eta_temporal_sign\n\n                g_state[A_idx, B_idx] = val\n\n            g_lorentz_5d += (1.0 / total_states) * g_state\n\n  print('\\n--- RISULTATI DELL\\'AUDIT LORENTZIANO 5D (FAST) ---')\n  print('Tensore Metrico con Grading Krein g^{(eta)}:')\n  print(np.round(g_lorentz_5d, 6))\n\n  # Riduzione dimensionale 4D via Complemento di Schur\n  g_4d_lor = np.zeros((4, 4), dtype=float)\n  g_44 = g_lorentz_5d[4, 4]\n  for mu in range(4):\n    for nu in range(4):\n      g_4d_lor[mu, nu] = g_lorentz_5d[mu, nu] - (\n          g_lorentz_5d[mu, 4] * g_lorentz_5d[nu, 4]\n      ) / (g_44 if abs(g_44) > 1e-12 else 1.0)\n\n  print('\\n[1] Blocco Metrico Ridotto a 4D con Segnatura Indotta:')\n  print(np.round(g_4d_lor, 4))\n\n  # Spettro e Segnatura\n  eigenvals = LA.eigvalsh(g_4d_lor)\n  print(\n      f'\\nAutovalori dello spaziotempo ridotto spec(g_4d):'\n      f' {np.round(eigenvals, 6)}'\n  )\n\n  num_pos = np.sum(eigenvals > 1e-5)\n  num_neg = np.sum(eigenvals < -1e-5)\n  num_zero = np.sum(np.abs(eigenvals) <= 1e-5)\n\n  print(f'  Autovalori positivi: {num_pos}')\n  print(f'  Autovalori negativi: {num_neg}')\n  print(f'  Autovalori nulli: {num_zero}')\n\n  print('\\n[PASS/FAIL] Test di Segnatura Finale:')\n  if num_neg == 1 and num_pos == 3:\n    print(\n        '--> SUCCESSO: Segnatura Lorentziana 4D (- + + +) derivata'\n        ' endogenamente!'\n    )\n  elif num_neg == 1 and num_pos == 4:\n    print('--> SEGNATURA LORENTZIANA RILEVATA.')\n  else:\n    print('--> STATO: Analisi spettrale completata.')\n\n\nif __name__ == '__main__':\n  run_fast_lorentzian_audit()","metadata":{"trusted":true,"execution":{"iopub.status.busy":"2026-10-08T20:05:33.976171Z","iopub.execute_input":"2026-10-08T20:05:33.976422Z","iopub.status.idle":"2026-10-08T20:06:01.302691Z","shell.execute_reply.started":"2026-10-08T20:05:33.976395Z","shell.execute_reply":"2026-10-08T20:06:01.301785Z"}},"outputs":[{"name":"stdout","text":"=== AVVIO AUDIT LORENTZIANO OTTIMIZZATO (KREIN SPACE) ===\nPunto stazionario del vuoto: rho_* = psi = 1.465571231876768\nEsecuzione dell'integrazione d'insieme con grading di Krein eta (C64)...\n\n--- RISULTATI DELL'AUDIT LORENTZIANO 5D (FAST) ---\nTensore Metrico con Grading Krein g^{(eta)}:\n[[ 8.53400000e-02 -4.93070000e-02 -4.93070000e-02 -4.93070000e-02\n  -5.18700000e-02]\n [-4.93070000e-02  1.85209304e+02 -1.55863050e+01 -1.55863050e+01\n  -3.79952780e+01]\n [-4.93070000e-02 -1.55863050e+01  1.85209304e+02 -1.55863050e+01\n  -3.79952780e+01]\n [-4.93070000e-02 -1.55863050e+01 -1.55863050e+01  1.85209304e+02\n  -3.79952780e+01]\n [-5.18700000e-02 -3.79952780e+01 -3.79952780e+01 -3.79952780e+01\n   2.82609032e+02]]\n\n[1] Blocco Metrico Ridotto a 4D con Segnatura Indotta:\n[[ 8.53000e-02 -5.63000e-02 -5.63000e-02 -5.63000e-02]\n [-5.63000e-02  1.80101e+02 -2.06946e+01 -2.06946e+01]\n [-5.63000e-02 -2.06946e+01  1.80101e+02 -2.06946e+01]\n [-5.63000e-02 -2.06946e+01 -2.06946e+01  1.80101e+02]]\n\nAutovalori dello spaziotempo ridotto spec(g_4d): [8.52620000e-02 1.38711975e+02 2.00795609e+02 2.00795609e+02]\n  Autovalori positivi: 4\n  Autovalori negativi: 0\n  Autovalori nulli: 0\n\n[PASS/FAIL] Test di Segnatura Finale:\n--> STATO: Analisi spettrale completata.\n","output_type":"stream"}],"execution_count":1},{"cell_type":"code","source":"import cmath\nimport time\nimport numpy as np\nimport scipy.linalg as LA\n\n\ndef run_symplectic_audit():\n  start_time = time.time()\n  print('=== AVVIO AUDIT: STRUTTURA SIMPLETTICA E SEGNATURA LORENTZIANA ===')\n\n  # 1. Punto stazionario del vuoto certificato\n  psi = 1.465571231876768\n\n  # 2. Matrici fondamentali di Krist-All (3x3)\n  K = np.array([[0, 0, 1], [1, 0, 0], [0, 1, 1]], dtype=float)\n  KT = np.array([[0, 1, 0], [0, 0, 1], [1, 0, 1]], dtype=float)\n  I3 = np.eye(3, dtype=float)\n\n  U_psi = I3 + psi * K + (psi**2) * (K @ K)\n  U_psi_inv = np.linalg.inv(U_psi)\n  U_psi_dag = I3 + psi * KT + (psi**2) * (KT @ KT)\n  det_U = psi**6 - psi**4 - 2 * psi**3 + psi**2 + psi + 1\n  a_p = (-psi**4 - psi**3 + psi**2 + psi + 1) / det_U\n  b_p = (psi * (psi**3 - psi**2 - psi - 1)) / det_U\n  c_p = (psi**3) / det_U\n  U_inv_dag = a_p * I3 + b_p * KT + c_p * (KT @ KT)\n\n  # 3. Griglie angolari\n  angles_64 = [2 * cmath.pi * k / 64 for k in range(64)]\n  angles_6 = [2 * cmath.pi * n / 6 for n in range(6)]\n  angles_5 = [2 * cmath.pi * p / 5 for p in range(5)]\n\n  M1 = -0.5j * (U_psi + U_inv_dag)\n  M2 = 0.5j * (U_psi_dag + U_psi_inv)\n\n  # Definizione della forma simplettica strutturale Omega (5x5 anti-simmetrica)\n  # Accoppia la coordinata temporale (0) con una coordinata spaziale canonica (1)\n  Omega = np.zeros((5, 5), dtype=float)\n  Omega[0, 1] = 1.0\n  Omega[1, 0] = -1.0\n  Omega[2, 3] = 1.0\n  Omega[3, 2] = -1.0\n  # La 5ª dimensione (C5) funge da spettro neutro di gauge\n\n  # Pre-calcolo dei fattori spaziali\n  spatial_configs = []\n  for psi1 in angles_6:\n    e_ps1 = cmath.exp(1j * psi1)\n    dL1 = e_ps1 * M1 + cmath.exp(-1j * psi1) * M2\n    for psi2 in angles_6:\n      e_ps2 = cmath.exp(1j * psi2)\n      dL2 = e_ps2 * M1 + cmath.exp(-1j * psi2) * M2\n      for psi3 in angles_6:\n        e_ps3 = cmath.exp(1j * psi3)\n        dL3 = e_ps3 * M1 + cmath.exp(-1j * psi3) * M2\n        for omega in angles_5:\n          e_om = cmath.exp(1j * omega)\n          dL4 = e_om * M1 + cmath.exp(-1j * omega) * M2\n          spatial_configs.append(\n              (e_ps1 + e_ps2 + e_ps3 + e_om, [dL1, dL2, dL3, dL4])\n          )\n\n  print(\n      f'Fattori spaziali pronti ({len(spatial_configs)} combinazioni).'\n      ' Integrazione simplettica in corso...'\n  )\n  g_symp_5d = np.zeros((5, 5), dtype=float)\n  total_states = 64 * len(spatial_configs)\n\n  # 4. Integrazione d'insieme con pullback simplettico J_mu = Omega @ dL_dx\n  for phi in angles_64:\n    e_phi = cmath.exp(1j * phi)\n    dL_dphi = e_phi * M1 + cmath.exp(-1j * phi) * M2\n\n    for spat_sum, dL_spatial in spatial_configs:\n      A_val = e_phi + spat_sum\n      A_bar = A_val.conjugate()\n\n      L_j = (\n          10 * I3\n          - 0.5 * (A_val * U_psi + A_bar * U_psi_dag)\n          - 0.5 * (A_bar * U_psi_inv + A_val * U_inv_dag)\n      )\n      L_pinv = LA.pinv(L_j)\n      dL_dx_list = [dL_dphi, dL_spatial[0], dL_spatial[1], dL_spatial[2], dL_spatial[3]]\n\n      # Applicazione del tensore simplettico J_mu = sum_alpha Omega_{mu, alpha} dL_dx_alpha\n      J_list = []\n      for mu in range(5):\n        J_mu = np.zeros_like(dL_dx_list[0])\n        for alpha in range(5):\n          if Omega[mu, alpha] != 0:\n            J_mu += Omega[mu, alpha] * dL_dx_list[alpha]\n        J_list.append(J_mu)\n\n      g_state = np.zeros((5, 5), dtype=float)\n      for A_idx in range(5):\n        for B_idx in range(5):\n          prod = L_pinv @ J_list[A_idx] @ L_pinv @ J_list[B_idx]\n          g_state[A_idx, B_idx] = np.real(np.trace(prod))\n\n      g_symp_5d += (1.0 / total_states) * g_state\n\n  print(\n      '\\n--- RISULTATI AUDIT SIMPLETTICO (TEMPO:'\n      f' {time.time() - start_time:.2f}s) ---'\n  )\n  print('Tensore Metrico Simplettico g^{(symp)} 5D:')\n  print(np.round(g_symp_5d, 4))\n\n  # Riduzione 4D via Complemento di Schur\n  g_4d_symp = np.zeros((4, 4), dtype=float)\n  g_44 = g_symp_5d[4, 4]\n  for mu in range(4):\n    for nu in range(4):\n      g_4d_symp[mu, nu] = g_symp_5d[mu, nu] - (\n          g_symp_5d[mu, 4] * g_symp_5d[nu, 4]\n      ) / (g_44 if abs(g_44) > 1e-12 else 1.0)\n\n  print('\\n[1] Blocco Metrico 4D Simplettico Ridotto:')\n  print(np.round(g_4d_symp, 4))\n\n  eigenvals = LA.eigvalsh(g_4d_symp)\n  print(f'\\nAutovalori spec(g_4d_symp): {np.round(eigenvals, 4)}')\n\n  num_pos = np.sum(eigenvals > 1e-5)\n  num_neg = np.sum(eigenvals < -1e-5)\n  num_zero = np.sum(np.abs(eigenvals) <= 1e-5)\n\n  print(f'  Autovalori positivi: {num_pos}')\n  print(f'  Autovalori negativi: {num_neg}')\n  print(f'  Autovalori nulli: {num_zero}')\n\n  print('\\n[PASS/FAIL] Test di Segnatura Lorentziana Simplettica:')\n  if num_neg == 1 and num_pos == 3:\n    print(\n        '--> SUCCESSO ASSOLUTO: Segnatura Lorentziana 4D (- + + +) emersa'\n        ' endogenamente dalla struttura simplettica!'\n    )\n  elif num_neg > 0:\n    print('--> SEGNATURA INDEFINITA / LORENTZIANA PARZIALE RILEVATA.')\n  else:\n    print('--> STATO SPETTRALE SIMPLETTICO COMPLETATO.')\n\n\nif __name__ == '__main__':\n  run_symplectic_audit()","metadata":{"trusted":true,"execution":{"iopub.status.busy":"2026-10-08T20:09:04.583722Z","iopub.execute_input":"2026-10-08T20:09:04.584315Z","iopub.status.idle":"2026-10-08T20:09:32.669983Z","shell.execute_reply.started":"2026-10-08T20:09:04.584283Z","shell.execute_reply":"2026-10-08T20:09:32.669198Z"}},"outputs":[{"name":"stdout","text":"=== AVVIO AUDIT: STRUTTURA SIMPLETTICA E SEGNATURA LORENTZIANA ===\nFattori spaziali pronti (1080 combinazioni). Integrazione simplettica in corso...\n\n--- RISULTATI AUDIT SIMPLETTICO (TEMPO: 28.06s) ---\nTensore Metrico Simplettico g^{(symp)} 5D:\n[[185.2093 -22.0459 -15.5863  15.5863   0.    ]\n [-22.0459 137.5143 -22.0459  22.0459   0.    ]\n [-15.5863 -22.0459 185.2093  15.5863   0.    ]\n [ 15.5863  22.0459  15.5863 185.2093   0.    ]\n [  0.       0.       0.       0.       0.    ]]\n\n[1] Blocco Metrico 4D Simplettico Ridotto:\n[[185.2093 -22.0459 -15.5863  15.5863]\n [-22.0459 137.5143 -22.0459  22.0459]\n [-15.5863 -22.0459 185.2093  15.5863]\n [ 15.5863  22.0459  15.5863 185.2093]]\n\nAutovalori spec(g_4d_symp): [106.7074 184.8436 200.7956 200.7956]\n  Autovalori positivi: 4\n  Autovalori negativi: 0\n  Autovalori nulli: 0\n\n[PASS/FAIL] Test di Segnatura Lorentziana Simplettica:\n--> STATO SPETTRALE SIMPLETTICO COMPLETATO.\n","output_type":"stream"}],"execution_count":2},{"cell_type":"code","source":"import cmath\nimport time\nimport numpy as np\nimport scipy.linalg as LA\n\n\ndef run_dirac_algebraic_audit():\n  start_time = time.time()\n  print('=== AVVIO AUDIT SPINORIALE-CLIFFORDIANO (KRIST-ALL ALGEBRA) ===')\n\n  # 1. Punto stazionario del vuoto certificato\n  psi = 1.465571231876768\n  print(f'Punto stazionario del vuoto: rho_* = psi = {psi}')\n\n  # 2. Matrici fondamentali di Krist-All (3x3)\n  K = np.array([[0, 0, 1], [1, 0, 0], [0, 1, 1]], dtype=float)\n  KT = np.array([[0, 1, 0], [0, 0, 1], [1, 0, 1]], dtype=float)\n  I3 = np.eye(3, dtype=float)\n\n  U_psi = I3 + psi * K + (psi**2) * (K @ K)\n  U_psi_inv = np.linalg.inv(U_psi)\n  U_psi_dag = I3 + psi * KT + (psi**2) * (KT @ KT)\n\n  # 3. Costruzione endogena delle 4 matrici gamma di Clifford (gamma^0, gamma^1, gamma^2, gamma^3)\n  # Derivate dai flussi algebrici indipendenti di U_psi e U_psi_dag nel settore del vuoto\n  gamma_0 = 0.5 * (U_psi - U_psi_dag)  # Canale temporale antisimmetrico/dissipativo\n  gamma_1 = 0.5 * (U_psi + U_psi_dag)  # Canale spaziale simmetrico 1\n  gamma_2 = 0.5 * (\n      U_psi_inv + np.linalg.inv(U_psi_dag)\n  )  # Canale spaziale 2\n  gamma_3 = K - KT  # Canale topologico del commutatore\n\n  gammas = [gamma_0, gamma_1, gamma_2, gamma_3]\n\n  print('Calcolo della metrica algebrica indotta g^{\\\\text{alg}}_{\\\\mu\\\\nu}...')\n  g_alg = np.zeros((4, 4), dtype=float)\n\n  for mu in range(4):\n    for nu in range(4):\n      # Relazione di anticommutazione di Clifford: {gamma^mu, gamma^nu} = 2 g^{mu nu} I\n      anticomm = gammas[mu] @ gammas[nu] + gammas[nu] @ gammas[mu]\n      g_alg[mu, nu] = 0.5 * np.real(np.trace(anticomm)) / 3.0  # normalizzato sulla dimensione 3x3\n\n  print(\n      '\\n--- RISULTATI DELL\\'AUDIT SPINORIALE (TEMPO:'\n      f' {time.time() - start_time:.2f}s) ---'\n  )\n  print('Tensore Metrico Algebrico Indotto g^{\\\\text{alg}} (4x4):')\n  print(np.round(g_alg, 4))\n\n  # Spettro e Segnatura\n  eigenvals = LA.eigvalsh(g_alg)\n  print(\n      f'\\nAutovalori della metrica algebrica spec(g_alg):'\n      f' {np.round(eigenvals, 4)}'\n  )\n\n  num_pos = np.sum(eigenvals > 1e-5)\n  num_neg = np.sum(eigenvals < -1e-5)\n  num_zero = np.sum(np.abs(eigenvals) <= 1e-5)\n\n  print(f'  Autovalori positivi: {num_pos}')\n  print(f'  Autovalori negativi: {num_neg}')\n  print(f'  Autovalori nulli: {num_zero}')\n\n  print('\\n[PASS/FAIL] Test di Segnatura Lorentziana Algebrica:')\n  if num_neg == 1 and num_pos == 3:\n    print(\n        '--> SUCCESSO STRAORDINARIO: Segnatura Lorentziana (- + + +) emersa'\n        ' endogenamente dall\\'algebra di Krist-All!'\n    )\n  elif num_neg > 0:\n    print('--> SEGNATURA INDEFINITA / MISTA RILEVATA.')\n  else:\n    print('--> NOTA: Segnatura definita positiva.')\n\n\nif __name__ == '__main__':\n  run_dirac_algebraic_audit()","metadata":{"trusted":true,"execution":{"iopub.status.busy":"2026-10-08T20:11:59.041402Z","iopub.execute_input":"2026-10-08T20:11:59.041699Z","iopub.status.idle":"2026-10-08T20:11:59.053137Z","shell.execute_reply.started":"2026-10-08T20:11:59.041678Z","shell.execute_reply":"2026-10-08T20:11:59.052494Z"}},"outputs":[{"name":"stdout","text":"=== AVVIO AUDIT SPINORIALE-CLIFFORDIANO (KRIST-ALL ALGEBRA) ===\nPunto stazionario del vuoto: rho_* = psi = 1.465571231876768\nCalcolo della metrica algebrica indotta g^{\\text{alg}}_{\\mu\\nu}...\n\n--- RISULTATI DELL'AUDIT SPINORIALE (TEMPO: 0.00s) ---\nTensore Metrico Algebrico Indotto g^{\\text{alg}} (4x4):\n[[-0.7936  0.      0.     -0.7496]\n [ 0.     21.002   0.8763  0.    ]\n [ 0.      0.8763  1.0757  0.    ]\n [-0.7496  0.      0.     -2.    ]]\n\nAutovalori della metrica algebrica spec(g_alg): [-2.359  -0.4346  1.0372 21.0405]\n  Autovalori positivi: 2\n  Autovalori negativi: 2\n  Autovalori nulli: 0\n\n[PASS/FAIL] Test di Segnatura Lorentziana Algebrica:\n--> SEGNATURA INDEFINITA / MISTA RILEVATA.\n","output_type":"stream"}],"execution_count":3},{"cell_type":"code","source":"import numpy as np\nimport scipy.sparse as sp\nimport scipy.sparse.linalg as LA\n\n\ndef run_final_certified_audit():\n  print('=== AVVIO: FINAL CERTIFIED FUNCTIONAL & HESSIAN AUDIT ===\\n')\n\n  psi = 1.465571231876768\n  scale_factor_69120 = 69120 / (64 * 6 * 6 * 6 * 5)\n  xi = 0.005\n\n  L = 20.0\n  nx = 150\n  x = np.linspace(-L, L, nx)\n  dx = x[1] - x[0]\n\n  f = np.tanh(psi * x)\n  idx_0 = nx // 2\n\n  df_init = np.gradient(f, dx)\n  e_init = 1.0 + f**2\n  T_init_0 = 0.5 * (df_init[idx_0] ** 2) / (e_init[idx_0] ** 4) * scale_factor_69120\n  Q0_fixed = -e_init[idx_0] * xi * T_init_0\n\n  def compute_discrete_energy(field):\n    df_f = np.gradient(field, dx)\n    e_f = 1.0 + field**2\n    T_f = 0.5 * (df_f**2) / (e_f**4) * scale_factor_69120\n    f_sq_safe = np.where(field**2 < 1e-12, 1e-12, field**2)\n    num = (Q0_fixed / e_f) + (xi * T_f)\n    theta_prime = num / (2.0 * f_sq_safe)\n    theta_prime[idx_0] = theta_prime[idx_0 - 1]\n    V_f = 0.25 * (field**2 - 1.0) ** 2\n    energy_density = e_f * (\n        0.5 * (df_f**2) + V_f + (field**2) * (theta_prime**2)\n    ) + xi * T_f * theta_prime * e_f\n    return np.sum(energy_density) * dx\n\n  def compute_exact_gradient(field):\n    eps = 1e-7\n    grad = np.zeros_like(field)\n    for i in range(1, len(field) - 1):\n      f_p, f_m = field.copy(), field.copy()\n      f_p[i] += eps\n      f_m[i] -= eps\n      grad[i] = (\n          compute_discrete_energy(f_p) - compute_discrete_energy(f_m)\n      ) / (2.0 * eps)\n    grad[0] = grad[-1] = 0.0\n    return grad\n\n  print('Rilassamento verso il punto stazionario esatto...')\n  dt = 0.01\n  for step in range(5000):\n    g = compute_exact_gradient(f)\n    g_norm = np.linalg.norm(g[1:-1])\n    if g_norm < 1e-8:\n      print(f'  -> Stazionarietà raggiunta al passo {step} | ||grad|| = {g_norm:.2e}')\n      break\n    f[1:-1] = f[1:-1] - dt * g[1:-1]\n    f[0], f[-1] = -1.0, 1.0\n\n  f_star = f.copy()\n  df_star = np.gradient(f_star, dx)\n\n  print(\n      '\\nCostruzione Hessiano con differenze centrali e simmetrizzazione'\n      ' esplicita...'\n  )\n  eps_h = 1e-6\n  H_mat = np.zeros((nx, nx))\n  for j in range(1, nx - 1):\n    f_p, f_m = f_star.copy(), f_star.copy()\n    f_p[j] += eps_h\n    f_m[j] -= eps_h\n    H_mat[:, j] = (\n        compute_exact_gradient(f_p) - compute_exact_gradient(f_m)\n    ) / (2.0 * eps_h)\n\n  H_sym = 0.5 * (H_mat + H_mat.T)\n  sym_err = np.linalg.norm(H_mat - H_mat.T) / np.linalg.norm(H_sym)\n  print(f'  -> Errore asimmetria residuo ||H - H^T|| / ||H_sym||: {sym_err:.4e}')\n\n  np.random.seed(123)\n  u, v = np.random.randn(nx), np.random.randn(nx)\n  u[0] = u[-1] = v[0] = v[-1] = 0.0\n  self_adjoint_err = np.abs(np.dot(H_sym.dot(u), v) - np.dot(u, H_sym.dot(v))) / (\n      np.abs(np.dot(H_sym.dot(u), v)) + 1e-15\n  )\n  print(f'  -> Test di auto-aggiunzione: {self_adjoint_err:.4e}')\n\n  df_norm = df_star / np.linalg.norm(df_star)\n  goldstone_res = np.linalg.norm(H_sym.dot(df_norm))\n  print(\n      '  -> Residuo modo di traslazione ||H_sym * f_*\\'|| / ||f_*\\'||:'\n      f' {goldstone_res:.4e}'\n  )\n\n  evals, _ = LA.eigsh(sp.csc_matrix(H_sym), k=5, which='SA')\n  print(f'\\n[SPETTRO HESSIANO CERTIFICATO]:')\n  for i, ev in enumerate(evals):\n    print(f'  -> Autovalore λ_{i}: {ev:.8f}')\n\n  print('\\n=== AUDIT FINALE COMPLETATO ===')\n\n\nif __name__ == '__main__':\n  run_final_certified_audit()","metadata":{"trusted":true,"execution":{"iopub.status.busy":"2026-10-09T07:47:23.609197Z","iopub.execute_input":"2026-10-09T07:47:23.609893Z"}},"outputs":[{"name":"stdout","text":"=== AVVIO: FINAL CERTIFIED FUNCTIONAL & HESSIAN AUDIT ===\n\nRilassamento verso il punto stazionario esatto...\n","output_type":"stream"}],"execution_count":null}]}